/**
 * An environmental report generated by the organization (US-27 to US-30).
 */
export type ReportType = 'consolidated' | 'period';
export type ReportStatus = 'available' | 'unavailable';

export class Report {
  constructor(
    public readonly id: string,
    public readonly title: string,
    public readonly type: ReportType,
    /** Period covered by the report. Consolidated reports use the latest period with data. */
    public readonly periodId: string,
    /** ISO 8601 date-time, generated by the repository (templates must not create dates). */
    public readonly generatedAt: string,
    public readonly status: ReportStatus,
    public readonly totalTonnesCo2e: number
  ) {}

  /** A report can be downloaded only when it is available (US-28, scenario 2). */
  get isDownloadable(): boolean {
    return this.status === 'available';
  }
}
